import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.DiAOIirN.js";import"./chunks/assets.CN5ja4nF.js";var a=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"osm-mcp","text":"The world map, in the conversation","tagline":"An MCP server for OpenStreetMap travel planning: geocoding, walking/driving/cycling routes, multi-stop optimization, isochrones and POI search — over free public services, with no API key.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Tools reference","link":"/reference/tools"},{"theme":"alt","text":"GitHub","link":"https://github.com/ni-c/osm-mcp"}]},"features":[{"title":"Walking routes that are actually walking routes","details":"The public OSRM demo servers ignore the profile inside the OSRM URL and always answer with car routes unless the FOSSGIS routed-foot/bike/car path prefixes are used. Most OSM MCP servers get this wrong; this one uses the prefixes, and its live smoke test asserts that foot routes come out much slower than car routes."},{"title":"Policy-compliant by construction","details":"Per-service client-side rate limiting, a mandatory identifying User-Agent, response caching, capped Overpass concurrency and automatic failover to an Overpass mirror on 429/5xx — the published usage policies of the shared community services are enforced in code."},{"title":"Eleven tools, or the three you need","details":"OSM_ALLOW_TOOLS cuts finer — essential for a curated six, your own comma-separated list, or a whole family with list_* — and OSM_DENY_TOOLS subtracts. Whatever is filtered out does not exist on the protocol rather than failing when called, and a name that matches no tool stops the server at startup instead of quietly going missing."},{"title":"No API key, read-only by design","details":"Every backend is a free public OpenStreetMap service and all 11 tools are read-only. The only optional secret is an OpenRouteService key, which is scrubbed from the environment after loading and redacted from error messages."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1788380634000}`),o={name:`index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[t(`figure`,{class:`diagram`},[t(`svg`,{viewBox:`0 0 720 436`,role:`img`,"aria-labelledby":`arch-title arch-desc`},[t(`title`,{id:`arch-title`},`osm-mcp architecture`),t(`desc`,{id:`arch-desc`},`An MCP client such as Claude talks to osm-mcp over stdio. The server exposes eleven read-only tools and calls the public OpenStreetMap services over HTTPS: Nominatim and Photon for geocoding, OSRM for routing, Valhalla for isochrones and Overpass for POI search. With an optional API key, routing, matrices and isochrones switch to OpenRouteService.`),t(`defs`,null,[t(`marker`,{id:`arch-arrow`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})]),t(`marker`,{id:`arch-arrow-accent`,class:`accent`,markerWidth:`9`,markerHeight:`9`,refX:`7`,refY:`3`,orient:`auto`},[t(`path`,{d:`M0,0 L7,3 L0,6 z`})])]),t(`rect`,{class:`node`,x:`20`,y:`170`,width:`160`,height:`80`,rx:`10`}),t(`text`,{class:`label-title`,x:`100`,y:`203`,"text-anchor":`middle`},`MCP client`),t(`text`,{class:`label-muted`,x:`100`,y:`223`,"text-anchor":`middle`},`Claude, Codex, …`),t(`rect`,{class:`node-accent`,x:`270`,y:`155`,width:`180`,height:`110`,rx:`10`}),t(`text`,{class:`label-title`,x:`360`,y:`188`,"text-anchor":`middle`},`osm-mcp`),t(`text`,{class:`label-muted`,x:`360`,y:`210`,"text-anchor":`middle`},`11 read-only tools`),t(`text`,{class:`label-muted`,x:`360`,y:`228`,"text-anchor":`middle`},`rate limits · cache`),t(`text`,{class:`label-muted`,x:`360`,y:`246`,"text-anchor":`middle`},`no API key required`),t(`path`,{class:`edge-accent`,d:`M180,210 L262,210`,"marker-end":`url(#arch-arrow-accent)`}),t(`text`,{class:`label-mono`,x:`221`,y:`198`,"text-anchor":`middle`},`stdio`),t(`rect`,{class:`node`,x:`550`,y:`20`,width:`150`,height:`56`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`43`,"text-anchor":`middle`},`Nominatim`),t(`text`,{class:`label-muted`,x:`625`,y:`61`,"text-anchor":`middle`},`geocoding`),t(`rect`,{class:`node`,x:`550`,y:`88`,width:`150`,height:`56`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`111`,"text-anchor":`middle`},`Photon`),t(`text`,{class:`label-muted`,x:`625`,y:`129`,"text-anchor":`middle`},`typo-tolerant search`),t(`rect`,{class:`node`,x:`550`,y:`156`,width:`150`,height:`56`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`179`,"text-anchor":`middle`},`OSRM`),t(`text`,{class:`label-muted`,x:`625`,y:`197`,"text-anchor":`middle`},`routing (FOSSGIS)`),t(`rect`,{class:`node`,x:`550`,y:`224`,width:`150`,height:`56`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`247`,"text-anchor":`middle`},`Valhalla`),t(`text`,{class:`label-muted`,x:`625`,y:`265`,"text-anchor":`middle`},`isochrones`),t(`rect`,{class:`node`,x:`550`,y:`292`,width:`150`,height:`56`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`315`,"text-anchor":`middle`},`Overpass`),t(`text`,{class:`label-muted`,x:`625`,y:`333`,"text-anchor":`middle`},`POI search · mirrors`),t(`rect`,{class:`node`,x:`550`,y:`360`,width:`150`,height:`56`,rx:`10`}),t(`text`,{class:`label-title`,x:`625`,y:`383`,"text-anchor":`middle`},`OpenRouteService`),t(`text`,{class:`label-muted`,x:`625`,y:`401`,"text-anchor":`middle`},`optional · API key`),t(`path`,{class:`edge`,d:`M450,180 L542,48`,"marker-end":`url(#arch-arrow)`}),t(`path`,{class:`edge`,d:`M450,192 L542,116`,"marker-end":`url(#arch-arrow)`}),t(`path`,{class:`edge`,d:`M450,204 L542,184`,"marker-end":`url(#arch-arrow)`}),t(`path`,{class:`edge`,d:`M450,216 L542,252`,"marker-end":`url(#arch-arrow)`}),t(`path`,{class:`edge`,d:`M450,228 L542,320`,"marker-end":`url(#arch-arrow)`}),t(`path`,{class:`edge edge-dashed`,d:`M450,240 L542,388`,"marker-end":`url(#arch-arrow)`}),t(`text`,{class:`label-mono`,x:`496`,y:`160`,"text-anchor":`middle`},`HTTPS`)]),t(`figcaption`,null,`The server speaks stdio, holds no credentials by default, and throttles itself below the published limits of every public OSM service it calls.`)],-1),r(`<p><img src="/demo.gif" alt="Terminal recording: the server lists its 11 tools, geocodes a place name and answers the same route on foot and by car — with the foot route several times slower, proving the FOSSGIS profile prefixes work" width="1260" height="400"></p><h2 id="in-one-command" tabindex="-1">In one command <a class="header-anchor" href="#in-one-command" aria-label="Permalink to “In one command”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">claude</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> mcp</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> add</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> osm</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> npx</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -y</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> osm-mcp</span></span></code></pre></div><p>No URL, no token — the public OpenStreetMap services are the default configuration. Then ask things like <em>&quot;how long is the walk from the Louvre to Notre-Dame?&quot;</em>, <em>&quot;plan the best order to visit these five places&quot;</em>, <em>&quot;what can I reach in 15 minutes on foot from my hotel?&quot;</em> or <em>&quot;find a fair cafe for the three of us to meet&quot;</em>.</p><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to “What it does not do”">​</a></h2><p>By design: no writes to OpenStreetMap (the API for that is not even wired up), no map image rendering, no GPS tracking, no traffic data, and no bulk geocoding — the client-side throttles that keep it inside the public services&#39; usage policies make it deliberately unsuitable for hammering. For heavy or commercial use, <a href="/guide/faq#can-i-use-this-for-heavy-or-commercial-workloads">self-host the backends</a> and point the <code>*_BASE_URL</code> variables at them. See <a href="/guide/security">Security</a>.</p><h2 id="running-it-elsewhere" tabindex="-1">Running it elsewhere <a class="header-anchor" href="#running-it-elsewhere" aria-label="Permalink to “Running it elsewhere”">​</a></h2><p>A client that cannot spawn a local process — ChatGPT connectors, Claude on the web, Cursor, LibreChat — cannot start osm-mcp the way Claude Code does. <a href="https://mcp-hub.ni-c.de" target="_blank" rel="noreferrer">mcp-hub</a> is the bridge: one container serves many stdio MCP servers over Streamable HTTP, with an OAuth 2.1 login behind a single password and long-lived tokens for the clients that cannot do OAuth. Its <code>/hub</code> endpoint puts every server behind six meta-tools, so one connector reaches all of them without N×tool schemas in the model&#39;s context, and it speaks both protocol revisions — a question this server asks travels through it to the person at the far end instead of ending at the gateway.</p><p>Its configuration is Claude Code&#39;s <code>mcpServers</code> format, so the entry you already have is the entry it takes: <a href="/guide/clients#through-mcp-hub">Through mcp-hub</a>.</p>`,9)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};